-- Report ID : RPT_542
-- Report    : Replenishment Parameters by Item Location
-- Module    : Replenishment
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     TRUNC(SYSDATE)                                        AS report_date,      im.DEPT                                               AS dept_no,     d.DEPT_NAME                                           AS dept_name,     im.CLASS                                              AS class_no,     c.CLASS_NAME                                          AS class_name,     im.SUBCLASS                                           AS subclass_no,     sc.SUB_NAME                                           AS subclass_name,      im.ITEM                                               AS item_id,     im.ITEM_DESC                                          AS item_description,     im.STANDARD_UOM                                       AS uom,     im.PACK_IND                                           AS pack_ind,     im.STATUS                                             AS item_status,      ril.LOCATION                                          AS location_id,     il.LOC_TYPE                                           AS loc_type,     CASE il.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                   AS loc_type_desc,     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS location_name,     il.STATUS                                             AS item_loc_status,     CASE il.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                   AS item_loc_status_desc,      ril.REPL_METHOD                                       AS repl_method,     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'DI' THEN 'Dynamic - Issues'         WHEN 'S'  THEN 'Dynamic - Seasonal'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'SO' THEN 'Store Orders'         WHEN 'T'  THEN 'Time Supply'         WHEN 'TI' THEN 'Time Supply - Issues'         WHEN 'E'  THEN 'Time Supply - Seasonal'         ELSE ril.REPL_METHOD     END                                                   AS repl_method_desc,     ril.STOCK_CAT                                         AS stock_category,     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'         ELSE ril.STOCK_CAT     END                                                   AS stock_category_desc,     ril.REPL_ORDER_CTRL                                   AS order_control,     CASE ril.REPL_ORDER_CTRL         WHEN 'A' THEN 'Automatic'         WHEN 'B' THEN 'Buyer Worksheet'         WHEN 'M' THEN 'Manual'         WHEN 'S' THEN 'Semi-Automatic'         ELSE ril.REPL_ORDER_CTRL     END                                                   AS order_control_desc,      ril.MIN_STOCK                                         AS min_stock,     ril.MAX_STOCK                                         AS max_stock,     ril.MIN_STOCK                                         AS reorder_point,     NVL(ril.MAX_STOCK, 0) - NVL(ril.MIN_STOCK, 0)        AS repl_band,     mra.PRES_STOCK                                        AS presentation_stock,     ril.DEMO_STOCK                                        AS demo_stock,     GREATEST(NVL(ils.STOCK_ON_HAND, 0)              - NVL(mra.PRES_STOCK, 0)              - NVL(ril.DEMO_STOCK, 0), 0)                 AS net_available_for_repl,      ril.SOURCE_WH                                         AS source_wh_id,     swh.WH_NAME                                           AS source_wh_name,     ril.PRIMARY_REPL_SUPPLIER                             AS supplier_id,     sp.SUP_NAME                                           AS supplier_name,     sp.SUP_STATUS                                         AS supplier_status,     isc.ORIGIN_COUNTRY_ID                                 AS origin_country,      ril.WH_LEAD_TIME                                      AS wh_to_store_lead_time,     isc.LEAD_TIME                                         AS supp_lead_time,     iscl.PICKUP_LEAD_TIME                                 AS loc_pickup_lt_override,     NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME)      AS effective_pickup_lt,     NVL(ril.SUPP_LEAD_TIME,    isc.LEAD_TIME)             AS effective_supp_lead_time,     ril.ADJ_SUPP_LEAD_TIME                                AS adj_supp_lead_time,     ril.ADJ_PICKUP_LEAD_TIME                              AS adj_pickup_lead_time,     NVL(NVL(iscl.PICKUP_LEAD_TIME, isc.PICKUP_LEAD_TIME), 0)         + NVL(ril.WH_LEAD_TIME, 0)                        AS total_pipeline_days,      ril.REVIEW_CYCLE                                      AS review_cycle,     CASE ril.REVIEW_CYCLE         WHEN '0'  THEN 'Every Week'         WHEN '1'  THEN 'Every Day'         WHEN '2'  THEN 'Every 2 Weeks'         WHEN '3'  THEN 'Every 3 Weeks'         WHEN '4'  THEN 'Every 4 Weeks'         WHEN '5'  THEN 'Every 5 Weeks'         WHEN '6'  THEN 'Every 6 Weeks'         WHEN '7'  THEN 'Every 7 Weeks'         WHEN '8'  THEN 'Every 8 Weeks'         WHEN '9'  THEN 'Every 9 Weeks'         WHEN '10' THEN 'Every 10 Weeks'         WHEN '11' THEN 'Every 11 Weeks'         WHEN '12' THEN 'Every 12 Weeks'         WHEN '13' THEN 'Every 13 Weeks'         WHEN '14' THEN 'Every 14 Weeks'         ELSE 'Every ' || ril.REVIEW_CYCLE || ' Weeks'     END                                                   AS review_cycle_desc,      NVL(rd_pivot.MON, 'N')                                AS review_mon,     NVL(rd_pivot.TUE, 'N')                                AS review_tue,     NVL(rd_pivot.WED, 'N')                                AS review_wed,     NVL(rd_pivot.THU, 'N')                                AS review_thu,     NVL(rd_pivot.FRI, 'N')                                AS review_fri,     NVL(rd_pivot.SAT, 'N')                                AS review_sat,     NVL(rd_pivot.SUN, 'N')                                AS review_sun,      ril.NON_SCALING_IND                                   AS scaling_exempt_ind,     CASE ril.NON_SCALING_IND         WHEN 'Y' THEN 'Scaling Exempt'         WHEN 'N' THEN 'Subject to Scaling'         ELSE 'Not Set'     END                                                   AS scaling_exempt_desc,     ril.MAX_SCALE_VALUE                                   AS max_scale_amount,      ril.PRIMARY_PACK_NO                                   AS primary_repl_pack,     prim_pack.ITEM_DESC                                   AS primary_repl_pack_desc,      mra.MIN_STOCK                                         AS master_min_stock,     mra.MAX_STOCK                                         AS master_max_stock,     mra.PRES_STOCK                                        AS master_pres_stock,     CASE         WHEN mra.ITEM IS NOT NULL              AND (NVL(ril.MIN_STOCK,-9) != NVL(mra.MIN_STOCK,-9)                OR NVL(ril.MAX_STOCK,-9) != NVL(mra.MAX_STOCK,-9))         THEN 'DIVERGED FROM MASTER'         WHEN mra.ITEM IS NULL THEN 'NO MASTER RECORD'         ELSE 'IN SYNC WITH MASTER'     END                                                   AS master_sync_status,      isc.SUPP_PACK_SIZE                                    AS supp_pack_size,     isc.INNER_PACK_SIZE                                   AS inner_pack_size,     isc.UNIT_COST                                         AS supplier_unit_cost,     isc.TI                                                AS pallet_tier,     isc.HI                                                AS pallet_high,     NVL(isc.TI, 0) * NVL(isc.HI, 0)         * NVL(isc.SUPP_PACK_SIZE, 1)                      AS pallet_order_multiple,      ils.STOCK_ON_HAND                                     AS current_soh,     ils.AV_COST                                           AS weighted_avg_cost,     il.SELLING_UNIT_RETAIL                                AS unit_retail,     ROUND(NVL(ils.STOCK_ON_HAND, 0) * NVL(ils.AV_COST, 0), 2)                                                           AS soh_cost_value,     CASE         WHEN NVL(ils.STOCK_ON_HAND, 0) = 0         THEN 'OUT OF STOCK'         WHEN NVL(ils.STOCK_ON_HAND, 0) < NVL(ril.MIN_STOCK, 0)         THEN 'BELOW MIN - REORDER REQUIRED'         WHEN NVL(ils.STOCK_ON_HAND, 0) BETWEEN              NVL(ril.MIN_STOCK, 0) AND NVL(ril.MAX_STOCK, 0)         THEN 'WITHIN RANGE'         WHEN NVL(ils.STOCK_ON_HAND, 0) > NVL(ril.MAX_STOCK, 0)         THEN 'ABOVE MAX - OVERSTOCK'         ELSE 'UNKNOWN'     END                                                   AS stock_position,     GREATEST(NVL(ril.MAX_STOCK, 0) - NVL(ils.STOCK_ON_HAND, 0), 0)                                                           AS implied_roq,      ril.LAST_UPDATE_DATETIME                              AS last_repl_attr_update  FROM     MFCS_RDS.RDS_WV_REPL_ITEM_LOC              ril      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC             il    ON  ril.ITEM                   = il.ITEM                                                      AND  ril.LOCATION               = il.LOC                                                      AND  ril.LOC_TYPE               = il.LOC_TYPE     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER          im    ON  ril.ITEM                   = im.ITEM                                                      AND  im.TRAN_LEVEL              = im.ITEM_LEVEL     JOIN  MFCS_RDS.RDS_WV_DEPS                 d     ON  im.DEPT                    = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS                c     ON  im.DEPT                    = c.DEPT                                                      AND  im.CLASS                   = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc    ON  im.DEPT                    = sc.DEPT                                                      AND  im.CLASS                   = sc.CLASS                                                      AND  im.SUBCLASS                = sc.SUBCLASS     LEFT JOIN MFCS_RDS.RDS_WV_STORE            st    ON  ril.LOCATION               = st.STORE                                                      AND  il.LOC_TYPE                = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH              wh     ON  ril.LOCATION               = wh.WH                                                      AND  il.LOC_TYPE                = 'W'     LEFT JOIN MFCS_RDS.RDS_WV_WH             swh     ON  ril.SOURCE_WH              = swh.WH     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH    ils    ON  ril.ITEM                   = ils.ITEM                                                      AND  ril.LOCATION               = ils.LOC                                                      AND  ils.LOC_TYPE               = ril.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc  ON  ril.ITEM                   = isc.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER  = isc.SUPPLIER                                                      AND  isc.PRIMARY_SUPP_IND       = 'Y'                                                      AND  isc.PRIMARY_COUNTRY_IND    = 'Y'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY_LOC iscl                                                       ON  ril.ITEM                   = iscl.ITEM                                                      AND  ril.PRIMARY_REPL_SUPPLIER  = iscl.SUPPLIER                                                      AND  iscl.LOC                   = ril.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp    ON  ril.PRIMARY_REPL_SUPPLIER  = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_MASTER_REPL_ATTR mra   ON  ril.ITEM                   = mra.ITEM                                                      AND  ril.LOCATION               = mra.LOCATION      LEFT JOIN (         SELECT             ITEM,             LOCATION,             MAX(CASE WHEN WEEKDAY = 1 THEN 'Y' ELSE 'N' END) AS MON,             MAX(CASE WHEN WEEKDAY = 2 THEN 'Y' ELSE 'N' END) AS TUE,             MAX(CASE WHEN WEEKDAY = 3 THEN 'Y' ELSE 'N' END) AS WED,             MAX(CASE WHEN WEEKDAY = 4 THEN 'Y' ELSE 'N' END) AS THU,             MAX(CASE WHEN WEEKDAY = 5 THEN 'Y' ELSE 'N' END) AS FRI,             MAX(CASE WHEN WEEKDAY = 6 THEN 'Y' ELSE 'N' END) AS SAT,             MAX(CASE WHEN WEEKDAY = 7 THEN 'Y' ELSE 'N' END) AS SUN         FROM  MFCS_RDS.RDS_WV_REPL_DAY         GROUP BY ITEM, LOCATION     ) rd_pivot                                            ON  ril.ITEM               = rd_pivot.ITEM                                                          AND  ril.LOCATION           = rd_pivot.LOCATION      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_MASTER     prim_pack                                                           ON  ril.PRIMARY_PACK_NO    = prim_pack.ITEM  WHERE     ril.REPL_METHOD  IS NOT NULL     AND il.STATUS    IN ('A','C')     AND im.STATUS     = 'A'  ORDER BY     d.DEPT_NAME,     c.CLASS_NAME,     sc.SUB_NAME,     im.ITEM_DESC,     il.LOC_TYPE,     CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END